        "चालक का अधिकृत, स्वस्थ और नशामुक्त होना आवश्यक है; कार्य से पूर्व सेफ्टी टॉक सुनें और सभी सुरक्षा उपकरण (हेलमेट, जूते, दस्ताने, चश्मा) पहनें। गमछा, टाई, ढीले कपड़े पहनना तथा कार्य व ड्राइविंग के दौरान मोबाइल फोन का उपयोग पूर्णतः वर्जित है।"
