          "Disc Insulators Inspection: Inspect the physical condition and integrity of disc insulators.",
          "Stay Wire Tension: Check and ensure proper tension in the stay wire assembly.",
          "Conductor Tension: Check and verify the correct sag and tension of ACSR conductors.",
          "Earth Wire Tension: Check and verify proper tension and continuity in the continuous earth wire.",
          "AB Switch & Jumpers: Verify smooth mechanical operation of Air Break (AB) switches and inspect all connecting jumpers.",
          "Drop Out (D.O.) Fuses: Inspect the condition, mounting, and elements of Drop Out (D.O.) fuses.",
          "Lightning Arrestors: Check lightning arrestors, including lead connections and terminal connectors.",
          "Road Crossing Guarding: Inspect road crossing safety cradle/guarding arrangements for structural security.",
          "Insulation Resistance Measurement: Measure the insulation resistance (IR value) of the overhead line and log the readings in the record register.",
