          "Battery Electrolyte & Charging Maintenance: Check battery fluid levels regularly and top them up as required (if applicable), ensuring charging routines adhere strictly to manufacturer instructions.",
          "Mechanical Lubrication & Cleaning: Clean the overall truck to keep debris from interfering with operation, and lubricate moving assemblies such as chains and bearings according to the preventive maintenance schedule.",
          "Scheduled Preventive Maintenance: Implement time-based preventive maintenance routines to proactively address emerging defects and minimize operational downtime.",
          "Circuit Grounding & Authorized Repairs: Ensure all service tools and charging outlets are properly grounded, and mandate that all maintenance and repairs are carried out exclusively by qualified personnel trained in electrical safety."
