    "en": [
      [
        "Workplace Conduct & Operational Discipline",
        [
          "Do not be in a state of intoxication at the workplace.",
          "Do not use mobile phones while work is in progress.",
          "Avoid wearing loose clothing, neckties, or towels while working.",
          "Ensure only trained and authorized persons operate the machine or crane."
        ]
      ],
      [
        "Personal Protective Equipment (PPE)",
        [
          "Wear all mandatory PPE before starting work, including safety shoes, safety helmet, hand gloves, and safety glasses.",
          "Always wear hand gloves when handling loads manually or working with metal wire ropes and slings."
        ]
      ],
      [
        "Hazard Control & Workshop Housekeeping",
        [
          "Verify the size, shape, weight, condition, lifting point, travel path, and landing position of the object before shifting.",
          "Ensure work area flooring is level and non-slippery.",
          "Maintain a safe clearance distance from personnel and surroundings during transit to prevent fouls and collisions.",
          "Take adequate precautions and deploy appropriate safety appliances when handling inflammable substances.",
          "Avoid stacking materials excessively high or storing objects inside walkways.",
          "Secure round objects that may roll out of position with wedges or blocks."
        ]
      ],
      [
        "Work Instruction / Procedure",
        [
          "Capacity & Thermal Verification: Handle loads only at normal temperatures, and lift manually only what you are capable of holding without exceeding personal physical capacity.",
          "Ergonomic Manual Lifting: Lift loads from a comfortable reach by bending the knees, keeping the back straight without strain, and balance the load properly before lifting.",
          "Manual Height & Pacing Limits: Lift loads manually only to a height that prevents injury from toppling or loss of control, and move at a controlled, slow walking pace while carrying the load.",
          "Mechanical Aids & Multi-Person Handling: Use appliances like crowbars, chain pulley blocks, hoist winches, or other handling equipment for heavy loads; use crowbars to displace heavy objects, and handle heavy, fragile, or bulky items with two or more persons.",
          "Crane & Rigging Capacity Checks: Ensure the crane is operated only by authorized personnel, the load magnitude never exceeds the crane's rated lifting capacity, and all wire ropes and slings have verified safe working capacity.",
          "Pre-Lift Rigging & Crane Position Inspection: Position and inspect the crane properly before lifting; inspect wire ropes and slings for damage (discarding damaged ones), ensure only competent persons perform slinging, and confirm all hands are clear before signaling the operator.",
          "Control Actuation & Electrical Clearance: Under no-load conditions, verify the trouble-free operation of all levers and controls, and maintain verified safe clearance distances from overhead electrical lines.",
          "Vertical Lift & Exclusion Zones: Lift loads purely vertically (never obliquely), ensure all personnel are clear before lifting, and strictly enforce a zero-entry policy under suspended loads.",
          "Boom Alignment & Swing Prevention: Ensure the boom extension and slewing angle are within safe operational limits before hoisting, and manage hoisting and placement carefully to prevent pendulum load swings.",
          "Outriggers, Wheel Chocks & Slew Lock: Deploy inbuilt outrigger jacks to relieve wheel loads, chock the wheels with stoppers where needed, and mechanically lock the slew system except during intentional slewing operations.",
          "Crane Marching / Transit Setup: Fully retract the boom and secure it horizontally in its rest groove to prevent swaying before moving or marching the crane."
        ],
        "ol"
      ]
    ],
