          "कार्य प्रगति पर होने के दौरान मोबाइल फोन का उपयोग बिल्कुल न करें।",
          "कार्य करते समय कभी भी ढीले कपड़े, तौलिया या नेक टाई न पहनें।",
          "मशीन का संचालन केवल प्रशिक्षित एवं अधिकृत कर्मियों द्वारा ही किया जाए।"
