          "Pedestrian Warning & Overhead Clearance: Never carry loads over people working below; sound an audible warning signal to allow personnel to clear the area.",
          "Hazardous Cargo Restriction: Never transport hot metal or materials lifted via magnets over personnel.",
          "Ground Dragging Prohibition: Do not use the crane to drag or pull loads while they are resting on the ground.",
          "Rigging & Movement Verification: Do not move the crane until the load is firmly rigged with slings, securely locked into the hook, and the hoist rope is drawn taut; confirm the load is properly balanced before traveling.",
