          "Visibility & Cleanliness: Maintain clean cab windows and glass doors at all times to ensure unobstructed visibility.",
          "Tool & Material Control: Strictly prohibit throwing or dropping any tools, materials, or equipment from the crane structure or cabin.",
          "Cabin Fire Protection: Check and ensure fire extinguishers in the cabin are present and properly maintained.",
          "Leaving the Cabin: Whenever leaving the cab for any reason, turn all control switches to the OFF position and take the operating key along.",
