          "सुरक्षित भार सीमा (SWL) का सत्यापन: लोड चार्ट के अनुसार आवश्यक बूम कोण और कार्यशील दायरे के लिए क्रेन की निर्धारित क्षमता (SWL) की जांच करें और सुनिश्चित करें कि कुल भार सीमा से अधिक न हो।",
          "रिगिंग उपकरणों का चयन व जांच: केवल प्रमाणित, दोषरहित स्लिंग्स, डी-शैकल और स्प्रेडर बार का उपयोग करें जिन पर क्षमता टैग मौजूद हो; मुड़े या क्षतिग्रस्त स्लिंग्स का उपयोग न करें।",
