          "ट्रायल लिफ्ट (परीक्षण उठाव): लोड को जमीन से लगभग 100 से 150 मिमी ऊपर उठाकर कुछ क्षण रोकें ताकि होइस्ट ब्रेक, क्रेन संतुलन और रिगिंग की स्थिरता की पुष्टि हो सके।",
          "प्रतिबंधित क्षेत्र एवं सिग्नल समन्वय: लिफ्टिंग और स्विंग क्षेत्र में बैरिकेडिंग करें तथा लटके भार के नीचे किसी को न जाने दें; केवल एक अधिकृत सिग्नलमैन (रिगर) के स्पष्ट हैंड सिग्नलों का ही पालन करें।",
          "नियंत्रित लैंडिंग एवं अनरिगिंग: लोड को समतल जमीन या लकड़ी के गुटकों (Cribbing) पर पूरी तरह सुरक्षित टिकाने के बाद ही वायर रोप ढीली करें और स्लिंग्स खोलें।",
          "कार्य समाप्ति उपरांत समेटना एवं हाउसकीपिंग: बूम को पूरी तरह समेटें, हुक को लॉक करें, आउटरिगर्स को सुरक्षित अंदर करें, सभी रिगिंग टूल्स को उचित स्थान पर रखें और क्रेन की पावर बंद करें।"
