          "Charging Kit Setup: Refit the charging valve; connect one side of the charging kit to the charging valve and the other side to a nitrogen gas cylinder; verify beforehand that it is a genuine nitrogen cylinder and check that it contains adequate pressure.",
          "Controlled Gas Charging: Open the charging valve, open the nitrogen cylinder using the cylinder key, and slowly regulate the gas using the regulator.",
          "Extension Length Check: Monitor the charged suspension cylinder extension length in accordance with OEM guidelines.",
          "Closure & Kit Removal: Close the nitrogen cylinder with the key and close the charging valve using the regulator; disconnect and remove the charging kit, and return the nitrogen cylinder to its designated storage area.",
          "Measurement Trial & Re-charging: Conduct a trial measurement to determine whether suspension charging is adequate; if required, repeat the gas charging process until the correct suspension extension length is achieved."
