          "ऐसा कोई भी कार्य न करें जो आपको स्पष्ट न हो; हमेशा शिफ्ट-इन-चार्ज या सुपरवाइजर के निर्देशों का पालन करें।",
          "शिफ्ट-इन-चार्ज या सुपरवाइजर की अनुमति के बिना कोई कार्य शुरू न करें; यदि कार्य स्पष्ट न हो या सुरक्षा संबंधी कोई शंका हो, तो बेझिझक बार-बार पूछें और चर्चा करें।",
