          "Hose & Piping Inspection: Thoroughly inspect all flexible rubber hoses and delivery piping for cracks, deterioration, or defects, and replace any damaged lines immediately.",
          "Nitrogen Cylinder Charging: Charge the actuation nitrogen cylinders carefully up to the required design operating pressure, adhering strictly to approved gas-charging safety practices.",
          "DCP Powder Assessment & Refueling: Inspect the dry chemical powder (DCP) at regular scheduled intervals; when refilling DCP powder, implement safety precautions to prevent powder contact or harm to any body part.",
          "Manual Actuation Readiness: Verify manual actuation capability; in the event that the system fails to fire automatically, manually trigger the system via the manual trigger switch or directly via the pilot cylinder.",
          "Post-Discharge Decontamination & Reset: In the event of an activation or fire event, turn off the system and thoroughly clean and remove all residual DCP powder from the equipment before releasing it back to service."
