          "क्रमिक इन्फ्लेशन एवं प्रेशर निगरानी: टायर में हवा धीरे-धीरे और चरणों में भरें—कभी भी तेजी से हवा भरने का प्रयास न करें। बीच-बीच में रुककर टायर को स्थिर होने दें और कैलिब्रेटेड प्रेशर गेज से लगातार दबाव मापें (कभी भी अनुमान पर निर्भर न रहें)। अधिक हवा भरने पर धीरे-धीरे डिफ्लेट करें; हवा को बहुत तेजी से बाहर न निकालें।",
          "लीकेज की जांच: वाल्व स्टेम या बीड के आसपास हवा के रिसाव को ध्यान से सुनें; लीकेज का पता चलने पर तुरंत प्रक्रिया रोकें और समस्या का समाधान करें।",
          "आपातकालीन प्रक्रियाएं: टायर फटने या विस्फोट होने पर तुरंत क्षेत्र खाली करें, आपातकालीन प्रोटोकॉल का पालन करें और सुरक्षित होने तक पास न जाएं। हवा का बड़ा रिसाव होने पर कार्य तुरंत रोकें।",
          "कार्य उपरांत सत्यापन: कैलिब्रेटेड गेज से निर्माता के अनुसार सही दबाव की पुष्टि करें, नई क्षति या रिसाव के लिए दोबारा निरीक्षण करें और वाल्व कैप को मजबूती से कसें।",
          "रिकॉर्ड, सफाई एवं हैंडओवर: अंतिम प्रेशर और किए गए सुधारों को मेंटेनेंस लॉग में दर्ज करें। कार्यस्थल से सभी होज और टूल्स हटाएं, तथा डंपर ऑपरेटर को कार्य पूर्ण होने व महत्वपूर्ण बिंदुओं की जानकारी दें।"
